import{_ as l,C as n,o as h,c as i,j as d,a as e,E as o,ah as r}from"./chunks/framework.DuX8SFU5.js";const A=JSON.parse('{"title":"AM_CAN_LOGGER — панель","description":"","frontmatter":{},"headers":[],"relativePath":"am_can_logger/dashboard.md","filePath":"am_can_logger/dashboard.md"}'),c={name:"am_can_logger/dashboard.md"};function s(_,t,p,b,m,u){const a=n("AssetImage");return h(),i("div",null,[t[0]||(t[0]=d("h1",{id:"am-can-logger-—-панель",tabindex:"-1"},[e("AM_CAN_LOGGER — панель "),d("a",{class:"header-anchor",href:"#am-can-logger-—-панель","aria-label":'Permalink to "AM_CAN_LOGGER — панель"'},"​")],-1)),t[1]||(t[1]=d("p",null,"Панель — программа для компьютера, к которому регистратор подключён по USB; сама страница открывается в браузере. Регистратор пишет и без неё: панель нужна, чтобы проверить запись, поставить отметки событий, забрать файлы и поменять настройки, не снимая карту.",-1)),o(a,{name:"am_can_logger_dashboard.webp",alt:"Панель: сессии на карте, загрузка шин CAN и поток записи на карту"}),t[2]||(t[2]=r('<h2 id="запуск" tabindex="-1">Запуск <a class="header-anchor" href="#запуск" aria-label="Permalink to &quot;Запуск&quot;">​</a></h2><p>Панели нужны Python 3 и пакеты <code>pymavlink</code> и <code>pyserial</code>. Порт регистратора одновременно может держать только одна программа, поэтому QGroundControl и другие инструменты на этом порту закрывают.</p><table tabindex="0"><thead><tr><th>Где регистратор</th><th>Что запускать</th></tr></thead><tbody><tr><td>На этом компьютере</td><td><code>python3 dashboard.py --port &lt;порт&gt;</code>, страница — <code>http://localhost:8080</code></td></tr><tr><td>На компьютере площадки, доступном по SSH</td><td><code>remote_dashboard.sh &lt;пользователь&gt;@&lt;адрес&gt;</code> (на Windows — <code>python am_canlog.py remote &lt;пользователь&gt;@&lt;адрес&gt;</code>): панель работает там, страница открывается здесь на <code>http://localhost:8080</code> через SSH-туннель</td></tr><tr><td>Там же, постоянно</td><td>Панель ставится на том компьютере службой (<code>canlog_service.sh install</code>): она переживает сбои и перезагрузки, а <code>remote_dashboard.sh</code> подключается к ней</td></tr></tbody></table><p>Если соединение пропало (ноутбук уснул или сменил сеть), панель, запущенная через <code>remote_dashboard.sh</code>, сама останавливается через 15 минут без открытых страниц и освобождает порт регистратора. Служба не останавливается; перед прошивкой регистратора её останавливают (<code>canlog_service.sh stop</code>).</p><h3 id="доступ-по-ссылке" tabindex="-1">Доступ по ссылке <a class="header-anchor" href="#доступ-по-ссылке" aria-label="Permalink to &quot;Доступ по ссылке&quot;">​</a></h3><p>Кнопка «Поделиться» в заголовке открывает панель в интернете для тех, у кого нет доступа к сети площадки, и закрывает её снова.</p><ul><li>Вход — по одному общему паролю; окно кнопки показывает ссылку и пароль и копирует их для отправки.</li><li>Вход действует 30 дней; смена пароля выходит всех.</li><li>Выбор сохраняется после перезапусков; у службы с постоянным именем ссылка не меняется.</li><li>Трафик идёт через внешний туннельный сервис, который может его видеть; при первом открытии сервис может показать свою страницу-предупреждение.</li><li>Вошедший может всё, что можно на месте: перезагрузить регистратор, поменять настройки, удалить файлы. Ссылку выключают, когда она не нужна.</li></ul><h2 id="заголовок" tabindex="-1">Заголовок <a class="header-anchor" href="#заголовок" aria-label="Permalink to &quot;Заголовок&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Элемент</th><th>Что показывает</th></tr></thead><tbody><tr><td>Состояние записи</td><td>Кадры в секунду и поток на карту; красный, пока теряются кадры. При наведении — каждая шина (поток, загрузка, скорость, потери в драйвере), потери по причинам, запись на карту и на сколько хватит свободного места</td></tr><tr><td>Здоровье</td><td>Загрузка процессора, память и температура процессора регистратора, средние за 5 с, и трафик страницы; жёлтый и красный — у пределов. При наведении — температуры IMU и барометра, канал до регистратора и задержка до панели</td></tr><tr><td>Кто здесь</td><td>Сколько человек открыли панель; при наведении — имена и последние действия, чтобы никто не перезагрузил регистратор посреди чужой выгрузки</td></tr><tr><td>Место на карте</td><td>Свободное место по данным самой карты</td></tr><tr><td>Кнопки</td><td>Доступ по ссылке, настройки, обновление списка файлов, перезагрузка регистратора, освобождение места, язык (английский, русский, татарский, хинди, испанский)</td></tr></tbody></table><p>Перезагрузка закрывает текущую сессию и начинает новую.</p><h2 id="графики" tabindex="-1">Графики <a class="header-anchor" href="#графики" aria-label="Permalink to &quot;Графики&quot;">​</a></h2><ul><li>«Шины CAN» — загрузка каждой шины с учётом битов стаффинга; заливка над линией — самые загруженные 100 мс. Зоны: зелёная до 50 %, оранжевая до 80 %, выше — красная. Подсказка легенды говорит, сколько кадров в секунду составляет полную шину при текущем трафике.</li><li>«SD-карта» — запись CAN, ULog, их сумма и потери. Зоны показывают ожидаемые потери при такой сумме: зелёная — без потерь, оранжевая — до 1 %, красная — больше. Предел здесь — остановки карты: каждая теряет то, что шины прислали сверх буфера, поэтому зоны считаются по самым долгим остановкам за последний час.</li></ul><p>Окно — 2, 10 или 30 минут из часа истории, которую хранит панель. Пауза (кнопка или пробел) останавливает графики, а данные продолжают копиться.</p><h2 id="отметки-событии" tabindex="-1">Отметки событий <a class="header-anchor" href="#отметки-событии" aria-label="Permalink to &quot;Отметки событий&quot;">​</a></h2><p>Перед действием на машине оператор пишет, что сейчас произойдёт («сейчас нажму запуск двигателя»), и нажимает «Отметить». Отметка сразу уходит на регистратор, даже во время выгрузки файла, и ложится в два места: в ULog, где её показывают PlotJuggler и Flight Review, и в файл <code>&lt;время&gt;_events.log</code> рядом с записью CAN, на часах кадров. На графиках отметки пронумерованы и перечислены под ними; страница сообщает, когда регистратор подтвердил отметку. В скобках после текста стоит имя, заданное в «Кто здесь».</p><p>При подключении панель выставляет часы регистратора по часам компьютера, поэтому время в записи и отметках настоящее. Без панели и без GPS часы после каждого включения начинаются с 2000 года, и тогда сессии различают по отметкам.</p><h2 id="фаилы-на-карте" tabindex="-1">Файлы на карте <a class="header-anchor" href="#фаилы-на-карте" aria-label="Permalink to &quot;Файлы на карте&quot;">​</a></h2><ul><li>Каждая сессия — одна строка: записи CAN, журнал ULog и отметки, новые сверху. В строке видна первая отметка сессии, остальные — в подсказке.</li><li>Отмеченные сессии, папку дня или всё сразу можно скачать или удалить. Записываемую сейчас сессию удалить нельзя, её файл держит регистратор; чтобы очистить карту полностью, регистратор сначала перезагружают.</li><li>Щелчок по файлу записи показывает сводку, не скачивая его: начало и конец, длительность, число кадров, поток, кадры по шинам. Панель читает только концы файла, поэтому число кадров оценочное и помечено «≈».</li></ul>',18)),o(a,{name:"am_can_logger_capture.webp",alt:"Сводка файла записи CAN и разбор шин по его началу"}),t[3]||(t[3]=r('<h3 id="выгрузка" tabindex="-1">Выгрузка <a class="header-anchor" href="#выгрузка" aria-label="Permalink to &quot;Выгрузка&quot;">​</a></h3><p>Файл идёт с регистратора на компьютер с панелью, где и остаётся, чтобы не тянуть его с карты повторно, а оттуда — на компьютер, где открыта страница: в папку загрузок браузера или в выбранную папку (Chrome и Edge). Записи CAN сохраняются как текст <code>candump</code>; вариант «как записано» (<code>.amcan</code>) втрое меньше. По USB выгрузка идёт со скоростью около 0,5 МБ/с. Файлы передаются по одному: PX4 ведёт один сеанс передачи файлов, поэтому очередь видна в панели, а передача из QGroundControl по тому же каналу прерывает выгрузку.</p><h2 id="разбор-шин" tabindex="-1">Разбор шин <a class="header-anchor" href="#разбор-шин" aria-label="Permalink to &quot;Разбор шин&quot;">​</a></h2><p>Протокол каждой шины задаётся в настройках или определяется по кадрам; панель пишет, по каким признакам. Разбор работает без файлов описаний (DBC, EDS):</p><table tabindex="0"><thead><tr><th>Протокол</th><th>Что видно</th></tr></thead><tbody><tr><td>DroneCAN</td><td>Узлы, их состояние и режим из NodeStatus, типы сообщений каждого узла</td></tr><tr><td>CANopen</td><td>Узлы, состояние и период heartbeat, аварийные сообщения EMCY</td></tr><tr><td>J1939</td><td>Устройства по address claim; неисправности DM1 с SPN и FMI, включая многопакетные; обороты, температура охлаждающей жидкости, давление масла, напряжение, моточасы и расход топлива двигателя</td></tr></tbody></table><p>Для каждой шины перечислены все типы сообщений с отправителями и числом кадров. Разбор файла на карте читает его первые 512 КиБ, около 5 с двух загруженных шин; скачанный файл разбирается целиком.</p><h2 id="сниффер" tabindex="-1">Сниффер <a class="header-anchor" href="#сниффер" aria-label="Permalink to &quot;Сниффер&quot;">​</a></h2>',7)),o(a,{name:"am_can_logger_sniffer.webp",alt:"Вкладка «Сниффер»: протокол, узлы и сообщения на каждой шине по живому потоку кадров"}),t[4]||(t[4]=d("p",null,"Вкладка «Сниффер» показывает тот же разбор по живому потоку кадров, а под ним — каждый идентификатор с частотой и последними данными. Регистратор шлёт поток, только пока вкладка открыта: по USB — каждый кадр, через беспроводной модуль — около 40 кадров в секунду целыми сообщениями, примерно 1 КиБ/с. На запись поток не влияет. Переключатель на вкладке выключает его совсем, для страницы и для GUI Tool; выбор сохраняется.",-1)),t[5]||(t[5]=d("p",null,[e("Тот же поток получает DroneCAN GUI Tool в сборке с интерфейсом "),d("code",null,"udp:"),e(": CAN1 — "),d("code",null,"udp:127.0.0.1:57740"),e(", CAN2 — "),d("code",null,"udp:127.0.0.1:57741"),e(". У каждой шины свои номера узлов, поэтому шины не сливаются в один интерфейс. При удалённом подключении адреса те же на своём компьютере: поток идёт через тот же SSH-туннель. Всё, что GUI Tool отправляет, отбрасывается: регистратор не передаёт в шины.")],-1)),t[6]||(t[6]=d("h2",{id:"настроики",tabindex:"-1"},[e("Настройки "),d("a",{class:"header-anchor",href:"#настроики","aria-label":'Permalink to "Настройки"'},"​")],-1)),o(a,{name:"am_can_logger_settings.webp",alt:"Окно настроек регистратора"}),t[7]||(t[7]=r('<table tabindex="0"><thead><tr><th>Настройка</th><th>Параметр</th><th>Замечание</th></tr></thead><tbody><tr><td>Шины, скорость, протокол</td><td><code>CANLOG_IFACES</code>, <code>CANLOG_BITRATE1/2</code>, <code>CANLOG_PROTO1/2</code></td><td>Список скоростей показывает, сколько кадров в секунду шина несёт при текущем трафике</td></tr><tr><td>Только прослушивание</td><td><code>CANLOG_SILENT</code></td><td>Выключают только на стенде, где больше некому подтверждать кадры</td></tr><tr><td>Длина файла</td><td><code>CANLOG_ROT_S</code></td><td>0 — один файл на сессию</td></tr><tr><td>Буфер</td><td><code>CANLOG_BUF_KB</code></td><td>Размер, который не помещается в память, регистратор уменьшает вдвое; панель показывает, сколько используется</td></tr><tr><td>Запуск при включении</td><td><code>CANLOG_EN</code></td><td></td></tr><tr><td>Содержимое ULog</td><td><code>SDLOG_PROFILE</code></td><td>Состояние регистратора или полный журнал PX4, с сырыми данными IMU или без</td></tr></tbody></table><p>Регистратор сохраняет настройки сразу, а применяет после перезагрузки; «Сохранить и перезагрузить» делает и то и другое. Каждое записанное значение панель сверяет с тем, что вернул регистратор.</p><p>При автоподборе регистратор слушает шину на скоростях 500, 250, 1000, 125, 800, 50, 20 и 10 кбит/с по очереди, пока не придут два кадра: на неверной скорости кадры не проходят проверку CRC. Первый файл ждёт скорость до 2,5 с, чтобы записать её в заголовок; кадры за это время копятся в буфере. Если позже на шине 3 с подряд одни ошибки, например регистратор переставили на другую шину, скорость определяется заново и начинается новый файл.</p>',3))])}const C=l(c,[["render",s]]);export{A as __pageData,C as default};
